import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { 
  GraduationCap, 
  Home, 
  Target, 
  Lightbulb, 
  TrendingUp, 
  Briefcase, 
  Brain,
  Bell,
  Menu,
  X
} from 'lucide-react';
import { useUser } from '../context/UserContext';
import { useNotifications } from '../context/NotificationContext';
import UserProfile from './UserProfile';
import './Navbar.css';

const Navbar = ({ onShowOnboarding }) => {
  const { user } = useUser();
  const { getUnreadCount } = useNotifications();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { path: '/', icon: Home, label: 'Dashboard' },
    { path: '/goals', icon: Target, label: 'Goals' },
    { path: '/recommendations', icon: Lightbulb, label: 'Learn' },
    { path: '/skill-assessment', icon: Brain, label: 'Skills' },
    { path: '/placement-prep', icon: Briefcase, label: 'Placements' },
    { path: '/progress', icon: TrendingUp, label: 'Progress' }
  ];

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <nav className="navbar">
      <div className="nav-container">
        {/* Logo */}
        <Link to="/" className="nav-logo">
          <GraduationCap size={32} />
          <span>LearnMate</span>
          <span className="engineering-badge">Engineering</span>
        </Link>

        {/* Desktop Navigation */}
        <div className="nav-menu desktop-only">
          {navItems.map(({ path, icon: Icon, label }) => (
            <Link
              key={path}
              to={path}
              className={`nav-link ${location.pathname === path ? 'active' : ''}`}
            >
              <Icon size={18} />
              <span>{label}</span>
            </Link>
          ))}
        </div>

        {/* User Info & Actions */}
        <div className="nav-actions">
          {user && (
            <div className="user-stats">
              <div className="stat-item points">
                <span className="stat-icon">⭐</span>
                <span className="stat-value">{user.points || 0}</span>
              </div>
              <div className="stat-item streak">
                <span className="stat-icon">🔥</span>
                <span className="stat-value">{user.streak || 0}</span>
              </div>
              <div className="stat-item placement-score">
                <span className="stat-icon">🎯</span>
                <span className="stat-value">{user.placementScore || 0}%</span>
              </div>
            </div>
          )}

          <button className="notification-btn">
            <Bell size={20} />
            {getUnreadCount() > 0 && (
              <span className="notification-badge">{getUnreadCount()}</span>
            )}
          </button>

          {user && (
            <div className="user-profile">
              <div className="user-avatar">
                {user.name?.charAt(0).toUpperCase()}
              </div>
              <div className="user-info">
                <span className="user-name">{user.name}</span>
                <span className="user-degree">{user.degree} {user.branch}</span>
              </div>
            </div>
          )}

          {/* Mobile Menu Toggle */}
          <button 
            className="mobile-menu-toggle mobile-only"
            onClick={toggleMobileMenu}
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Navigation */}
      <div className={`mobile-nav ${isMobileMenuOpen ? 'open' : ''}`}>
        {navItems.map(({ path, icon: Icon, label }) => (
          <Link
            key={path}
            to={path}
            className={`mobile-nav-link ${location.pathname === path ? 'active' : ''}`}
            onClick={() => setIsMobileMenuOpen(false)}
          >
            <Icon size={20} />
            <span>{label}</span>
          </Link>
        ))}
      </div>
    </nav>
  );
};

export default Navbar;
